  const readings=ids=>`<div class="field-readings"><span class="field-label">沿着馆藏继续读</span>${ids.map(id=>{const a=article(id);return a?`<a href="?article=${e(id)}">${e(a.title)} <b aria-hidden="true">↗</b></a>`:'';}).join('')}</div>`;
