  const keep=(key,val)=>{url.searchParams.set(key,val);history.replaceState(null,'',url);};
  const select=(items,key,fallback)=>items.find(i=>i.id===url.searchParams.get(key))?.id||fallback;
  const landing=`<section class="field-entrances" id="fieldrooms" id="fieldrooms" id="fieldrooms"><div class="section-heading"><div><p>研究所 · 开放展室</p><h2>把世界，放到手边。</h2></div></div><div class="field-room-grid">${rooms.map(r=>`<a href="?page=${r.id}" class="field-room"><img src="assets/${r.image}" alt="" loading="lazy"><div><span class="field-label">${r.n} / ${r.en}</span><h3>${r.name}<b aria-hidden="true">↗</b></h3><p>${r.desc}</p></div></a>`).join('')}</div></section>`;
  if(!page){main.querySelector('.desk-feature')?.insertAdjacentHTML('beforebegin',landing);return;}
  if(page==='library'){main.querySelector('.catalog-heading')?.insertAdjacentHTML('beforebegin',landing);return;}
  const room=rooms.find(r=>r.id===page);if(!room)return;
  document.title=room.name+' | 帷幕研究所';document.body.dataset.surface='fieldroom';document.body.dataset.collection=page;
